//! Exact project copies, recovery, and observation. Never operates on the Desktop original.
use std::{fs,io::Read,path::{Path,PathBuf}};
use serde_json::{Value,json};
use crate::studio_files as disk;
fn owner(directory:&str,project:&str)->Result<PathBuf,String>{let root=disk::root(directory)?;let v:Value=serde_json::from_slice(&fs::read(root.join("Studio Link/project.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if v["project"]["id"]!=project{return Err("This folder belongs to another project".into())}Ok(root)}
fn safe(root:&Path,rel:&str)->Result<PathBuf,String>{let rel=disk::relative(rel)?;let mut parent=root.join(&rel);while !parent.exists(){if !parent.pop(){return Err("Invalid media location".into())}}if !parent.canonicalize().map_err(|e|e.to_string())?.starts_with(root){return Err("Media location points outside the project".into())}let p=root.join(rel);if fs::symlink_metadata(&p).map(|m|m.file_type().is_symlink()).unwrap_or(false){return Err("Managed media cannot be a symbolic link".into())}Ok(p)}
fn equal(a:&Path,b:&Path)->Result<bool,String>{if fs::metadata(a).map_err(|e|e.to_string())?.len()!=fs::metadata(b).map_err(|e|e.to_string())?.len(){return Ok(false)}let(mut a,mut b)=(fs::File::open(a).map_err(|e|e.to_string())?,fs::File::open(b).map_err(|e|e.to_string())?);let(mut x,mut y)=([0;65536],[0;65536]);loop{let n=a.read(&mut x).map_err(|e|e.to_string())?;b.read_exact(&mut y[..n]).map_err(|e|e.to_string())?;if x[..n]!=y[..n]{return Ok(false)}if n==0{return Ok(true)}}}
fn copy(source:&Path,target:&Path)->Result<(),String>{if target.exists(){if equal(source,target)?{return Ok(())}return Err("A different file already occupies this media location".into())}let parent=target.parent().ok_or("Missing media folder")?;fs::create_dir_all(parent).map_err(|e|e.to_string())?;let temp=parent.join(format!(".copy-{}-{}.tmp",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos()));let result=(||{let mut input=fs::File::open(source).map_err(|e|e.to_string())?;let mut output=fs::OpenOptions::new().create_new(true).write(true).open(&temp).map_err(|e|e.to_string())?;std::io::copy(&mut input,&mut output).map_err(|e|e.to_string())?;output.sync_all().map_err(|e|e.to_string())?;drop(output);if !equal(source,&temp)?{return Err("The media changed during copying. Try attaching it again.".into())}if target.exists(){return Err("Media destination changed during copying".into())}fs::rename(&temp,target).map_err(|e|e.to_string())})();if result.is_err(){let _=fs::remove_file(temp);}result}
pub fn preserve(directory:String,project:String,files:Vec<Value>,stage:bool)->Result<Value,String>{let root=owner(&directory,&project)?;let _lock=crate::media_organization::lock(&root)?;let mut out=Vec::new();for mut f in files{let source=PathBuf::from(f["path"].as_str().ok_or("Missing media path")?).canonicalize().map_err(|_|"Cleanup file is missing")?;let mut ext=source.extension().and_then(|s|s.to_str()).unwrap_or("").to_ascii_lowercase();if !["png","jpg","jpeg","webp","gif","bmp","tif","tiff","mp4","mov","m4v","webm"].contains(&ext.as_str()){return Err("Unsupported cleanup media".into())}let original_fingerprint=crate::owned_output::file_fingerprint(&source)?;
 let mut original=None;let source=if let Some(data)=f["pngData"].as_str(){use base64::Engine;let bytes=base64::engine::general_purpose::STANDARD.decode(data).map_err(|e|e.to_string())?;if bytes.len()>256*1024*1024||!bytes.starts_with(b"\x89PNG\r\n\x1a\n"){return Err("Invalid converted PNG; the original was kept".into())}let fp=crate::owned_output::fingerprint(&bytes);let rel=format!("Studio Link/.incoming/png-{fp}.png");let target=safe(&root,&rel)?;if let Some(parent)=target.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?;}if target.exists(){if fs::read(&target).map_err(|e|e.to_string())?!=bytes{return Err("Converted PNG destination is occupied".into())}}else{use std::io::Write;let mut output=fs::OpenOptions::new().create_new(true).write(true).open(&target).map_err(|e|e.to_string())?;output.write_all(&bytes).and_then(|_|output.sync_all()).map_err(|e|e.to_string())?;}if f["managed"]==true{if let Ok(rel)=source.strip_prefix(&root){original=Some(json!({"relativePath":rel.to_string_lossy().replace('\\',"/"),"fingerprint":original_fingerprint}));}}ext="png".into();target}else{source};
 if let Some(map)=f.as_object_mut(){map.remove("pngData");}let fingerprint=crate::owned_output::file_fingerprint(&source)?;
 let mut obsolete=f["pendingRetirement"].as_array().cloned().unwrap_or_default();if let Some(old)=original{obsolete.push(old);}if let(Some(old),Some(fp))=(f["vaultRelativePath"].as_str(),f["fingerprint"].as_str()){if fp!=fingerprint{obsolete.push(json!({"relativePath":old,"fingerprint":fp}));}}if !obsolete.is_empty(){f["pendingRetirement"]=json!(obsolete);}
 let recovery=format!("Studio Link/.recovery/media/{fingerprint}.{ext}");let vault=safe(&root,&recovery)?;copy(&source,&vault)?;
 let existing=source.strip_prefix(&root).ok().map(|p|p.to_string_lossy().replace('\\',"/"));let id=f["id"].as_str().ok_or("Missing permanent media identity")?;if id.len()>200||!id.chars().all(|c|c.is_ascii_alphanumeric()||c=='-'){return Err("Invalid media identity".into())}
 let relative=if stage||existing.is_none(){format!("Studio Link/.incoming/{id}.{ext}")}else{existing.unwrap()};let target=safe(&root,&relative)?;if target!=source{copy(&vault,&target)?;}let(size,modified)=disk::metadata(&target)?;f["path"]=json!(target.to_string_lossy());f["relativePath"]=json!(relative);f["vaultRelativePath"]=json!(recovery);f["fingerprint"]=json!(fingerprint);f["contentFingerprint"]=f["fingerprint"].clone();f["managed"]=json!(true);f["name"]=json!(target.file_name().unwrap_or_default().to_string_lossy());f["size"]=json!(size);f["modified"]=json!(modified);f["missing"]=json!(false);f["state"]=json!("ok");out.push(f);
 }Ok(json!(out))}
pub fn restore(directory:String,project:String,files:Vec<Value>)->Result<Value,String>{let root=owner(&directory,&project)?;let _lock=crate::media_organization::lock(&root)?;let mut out=Vec::new();for mut f in files{let recovery=f["vaultRelativePath"].as_str().ok_or("No recovery copy exists for this cleanup")?;if !recovery.starts_with("Studio Link/.recovery/media/"){return Err("Invalid recovery location".into())}let source=safe(&root,recovery)?;if !source.exists(){return Err("The cleanup recovery copy is missing".into())}let target=safe(&root,f["relativePath"].as_str().ok_or("Missing project location")?)?;copy(&source,&target)?;let(size,modified)=disk::metadata(&target)?;f["path"]=json!(target.to_string_lossy());f["size"]=json!(size);f["modified"]=json!(modified);f["missing"]=json!(false);f["state"]=json!("ok");out.push(f);}Ok(json!(out))}
fn cached_fingerprint(path:&Path,size:u64,modified:u64)->Result<String,String>{
 use std::{sync::{Mutex,OnceLock},collections::HashMap};
 type Cache=Mutex<HashMap<(PathBuf,u64,u64),String>>;static CACHE:OnceLock<Cache>=OnceLock::new();let cache=CACHE.get_or_init(||Mutex::new(HashMap::new()));let key=(path.to_path_buf(),size,modified);
 if let Ok(c)=cache.lock(){if let Some(value)=c.get(&key){return Ok(value.clone())}}
 let value=crate::owned_output::file_fingerprint(path)?;if let Ok(mut c)=cache.lock(){if c.len()>8192{c.clear()}c.insert(key,value.clone());}Ok(value)
}
pub fn audit(directory:String,project:String,checks:Vec<Value>)->Result<Value,String>{let root=owner(&directory,&project)?;let _lock=crate::media_organization::lock(&root)?;let mut rows=Vec::new();for f in checks{let path=if let Some(rel)=f["relativePath"].as_str(){safe(&root,rel)?}else{PathBuf::from(f["path"].as_str().unwrap_or(""))};let mut row=f.clone();let state=match disk::metadata(&path){Ok((size,modified))=>{row["size"]=json!(size);row["modified"]=json!(modified);"ok"},Err(_)=>"missing"};row["state"]=json!(state);row["missing"]=json!(state=="missing");if state=="ok"&&f["role"]=="audio"&&f["fingerprint"].as_str().map(|fp|fp.starts_with("audio-v1-")).unwrap_or(false){row["observedFingerprint"]=crate::audio_identity::info(&path)?["fingerprint"].clone();}if state=="ok"&&f["verifyFingerprint"]==true{row["observedFingerprint"]=json!(cached_fingerprint(&path,row["size"].as_u64().unwrap_or(0),row["modified"].as_u64().unwrap_or(0))?);}rows.push(row);}let link=root.join("Studio Link");let mut records=Vec::new();for entry in fs::read_dir(link).map_err(|e|e.to_string())?{let path=entry.map_err(|e|e.to_string())?.path();if path.extension().and_then(|s|s.to_str())!=Some("json"){continue}let name=path.file_name().unwrap_or_default().to_string_lossy().to_string();match fs::read(&path).map_err(|e|e.to_string()).and_then(|b|serde_json::from_slice::<Value>(&b).map_err(|e|e.to_string())){Ok(v)=>records.push(json!({"name":name,"format":v["format"],"projectId":v["projectId"].as_str().or(v["project"]["id"].as_str()).or(v["studioProjectId"].as_str()),"sourceId":v["source"]["id"],"updatedAt":v["updatedAt"].as_str().or(v["createdAt"].as_str())})),Err(e)=>records.push(json!({"name":name,"error":e}))}}Ok(json!({"files":rows,"records":records}))}
pub fn retire_superseded(directory:String,project:String,files:Vec<Value>,retained:Vec<Value>)->Result<Value,String>{let root=owner(&directory,&project)?;let _lock=crate::media_organization::lock(&root)?;let catalog:Value=serde_json::from_slice(&fs::read(root.join("Studio Link/media-index.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let mut used=retained;for e in catalog["entries"].as_object().into_iter().flat_map(|m|m.values()){for field in ["files","referenceFiles","ignoredFiles"]{used.extend(e[field].as_array().into_iter().flatten().cloned());}}
 let mut removed=Vec::new();for f in files{let current=f["relativePath"].as_str().ok_or("Missing current cleanup")?;let fp=f["fingerprint"].as_str().ok_or("Missing current cleanup fingerprint")?;let recovery=f["vaultRelativePath"].as_str().ok_or("Missing current recovery")?;if crate::owned_output::file_fingerprint(&safe(&root,current)?)?!=fp||crate::owned_output::file_fingerprint(&safe(&root,recovery)?)?!=fp{return Err("The current cleanup changed during saving. Prior recovery was kept.".into())}
 for old in f["pendingRetirement"].as_array().into_iter().flatten(){let rel=old["relativePath"].as_str().ok_or("Missing obsolete media path")?;if rel==current||rel==recovery||used.iter().any(|u|u["relativePath"]==rel||u["vaultRelativePath"]==rel){continue}let path=safe(&root,rel)?;if !path.exists(){continue}if crate::owned_output::file_fingerprint(&path)?.as_str()!=old["fingerprint"].as_str().unwrap_or(""){continue}if rel.starts_with("Studio Link/.recovery/media/"){fs::remove_file(path).map_err(|e|e.to_string())?;}else{trash_file(&path)?;}removed.push(rel.to_owned());}}
 Ok(json!({"removed":removed}))}
pub fn trash(directory:String,project:String,files:Vec<Value>,retained:Vec<Value>)->Result<Value,String>{trash_with(directory,project,files,retained,trash_file)}
fn trash_with<F:Fn(&Path)->Result<(),String>>(directory:String,project:String,files:Vec<Value>,mut retained:Vec<Value>,send:F)->Result<Value,String>{let root=owner(&directory,&project)?;let _lock=crate::media_organization::lock(&root)?;let catalog:Value=serde_json::from_slice(&fs::read(root.join("Studio Link/media-index.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;for e in catalog["entries"].as_object().into_iter().flat_map(|m|m.values()).filter(|e|e["removed"]!=true){retained.extend(e["files"].as_array().into_iter().flatten().cloned());retained.extend(e["referenceFiles"].as_array().into_iter().flatten().cloned());}
 let mut plans=Vec::new();for f in &files{let key=json!([f["id"],f["fingerprint"]]).to_string();let mut paths=Vec::new();if f["managed"]==true{for field in ["relativePath","vaultRelativePath"]{if let Some(rel)=f[field].as_str(){if retained.iter().any(|u|["relativePath","vaultRelativePath"].iter().any(|k|u[*k].as_str()==Some(rel))){continue}let p=safe(&root,rel)?;if p.exists(){let fp=f["fingerprint"].as_str().ok_or("Unverified media cannot be moved to Trash")?;if crate::owned_output::file_fingerprint(&p)?!=fp{return Err("Archived media was edited. Refresh it before moving it to Trash.".into())}if !paths.contains(&rel.to_owned()){paths.push(rel.to_owned());}}}}}plans.push((key,paths));}
 let mut moved=Vec::new();let mut errors=Vec::new();let mut complete=Vec::new();for(key,paths)in plans{let mut ok=true;for rel in paths{let path=safe(&root,&rel)?;if !path.exists(){continue}match send(&path){Ok(())=>moved.push(rel),Err(e)=>{errors.push(format!("{rel}: {e}"));ok=false;break}}}if ok{complete.push(key);}else{break}}
 Ok(json!({"trashed":moved,"completedVersions":complete,"errors":errors}))}
fn trash_file(path:&Path)->Result<(),String>{use std::process::Command;
 #[cfg(target_os="macos")]let status=Command::new("osascript").args(["-l","JavaScript","-e","ObjC.import('Foundation'); function run(a){let error=Ref();if(!$.NSFileManager.defaultManager.trashItemAtURLResultingItemURLError($.NSURL.fileURLWithPath(a[0]),null,error))throw Error('Could not move file to Trash');}"]).arg(path).status();
 #[cfg(windows)]let status=Command::new("powershell").args(["-NoProfile","-NonInteractive","-Command","Add-Type -AssemblyName Microsoft.VisualBasic; [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($env:STUDIO_TRASH_PATH, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)"]).env("STUDIO_TRASH_PATH",path).status();
 #[cfg(all(not(target_os="macos"),not(windows)))]let status=Command::new("gio").arg("trash").arg("--").arg(path).status();
 if status.map_err(|e|format!("Trash is unavailable: {e}. The file was kept."))?.success(){Ok(())}else{Err("Could not move media to Trash. The archive entry was kept.".into())}}
pub fn compare(directory:String,project:String,outputs:Vec<Value>)->Result<Value,String>{use base64::Engine;let root=owner(&directory,&project)?;let _lock=crate::media_organization::lock(&root)?;let mut out=Vec::new();for f in outputs{let rel=f["oldPath"].as_str().or(f["relativePath"].as_str()).ok_or("Missing output path")?;let target=safe(&root,rel)?;let bytes=base64::engine::general_purpose::STANDARD.decode(f["base64Data"].as_str().ok_or("Missing preview bytes")?).map_err(|e|e.to_string())?;let existed=target.is_file();let changed=!existed||fs::read(&target).map_err(|e|e.to_string())?!=bytes;out.push(json!({"id":f["id"],"changed":changed,"existed":existed,"oldPath":if existed{Some(target.to_string_lossy().into_owned())}else{None}}));}Ok(json!(out))}

// Native backup location is supplied by AppHandle in lib.rs; tests use a temporary root.
pub fn backup(folder:&Path,project:&str,snapshot:&str,closing:bool)->Result<Value,String>{let raw:Value=serde_json::from_str(snapshot).map_err(|_|"Backup is not valid project JSON")?;if raw["format"]!="storyboardstudio-v01"||raw["project"]["id"]!=project||!raw["project"]["chapters"].is_array()||!raw["assets"].is_array(){return Err("Invalid project backup".into())}if !project.chars().all(|c|c.is_ascii_alphanumeric()||c=='-'){return Err("Invalid backup identity".into())}let dir=folder.join(project);fs::create_dir_all(&dir).map_err(|e|e.to_string())?;let mut versions=backup_files(&dir)?;let mut content=raw.clone();content.as_object_mut().unwrap().remove("exportedAt");if let Some(project)=content["project"].as_object_mut(){project.remove("lastOpenedAt");}let fingerprint=crate::owned_output::fingerprint(content.to_string().as_bytes());let now=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos();
 if let Some(path)=versions.last(){let old:Value=serde_json::from_slice(&fs::read(path).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let mut old_content=old.clone();old_content.as_object_mut().unwrap().remove("exportedAt");if let Some(project)=old_content["project"].as_object_mut(){project.remove("lastOpenedAt");}if let Some(project)=content["project"].as_object_mut(){project.remove("lastOpenedAt");}if old_content==content{return Ok(json!({"saved":false,"reason":"unchanged"}))}let age=fs::metadata(path).and_then(|m|m.modified()).ok().and_then(|t|t.elapsed().ok()).map(|d|d.as_secs()).unwrap_or(0);if !closing&&age<1200{return Ok(json!({"saved":false,"reason":"interval"}))}}
 let name=format!("{now}-{fingerprint}.StoryboardStudio");disk::atomic_json(&dir,&name,snapshot)?;versions=backup_files(&dir)?;let keep=versions.len().saturating_sub(4);let last=versions.last().cloned();for(i,path)in versions.iter().enumerate(){let age=fs::metadata(path).and_then(|m|m.modified()).ok().and_then(|t|t.elapsed().ok()).map(|d|d.as_secs()).unwrap_or(0);if Some(path)!=last.as_ref()&&(i<keep||age>864000){fs::remove_file(path).map_err(|e|e.to_string())?;}}Ok(json!({"saved":true,"path":dir.join(name).to_string_lossy()}))}
pub fn backup_files(dir:&Path)->Result<Vec<PathBuf>,String>{if !dir.exists(){return Ok(Vec::new())}let mut files=Vec::new();for e in fs::read_dir(dir).map_err(|e|e.to_string())?{let path=e.map_err(|e|e.to_string())?.path();if path.extension().and_then(|x|x.to_str())==Some("StoryboardStudio"){if let Ok(v)=fs::read(&path).map_err(|e|e.to_string()).and_then(|b|serde_json::from_slice::<Value>(&b).map_err(|e|e.to_string())){if v["format"]=="storyboardstudio-v01"&&v["project"]["chapters"].is_array()&&v["assets"].is_array(){files.push(path)}}}}files.sort_by_key(|p|(fs::metadata(p).and_then(|m|m.modified()).ok().and_then(|t|t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d|d.as_nanos()).unwrap_or(0),p.clone()));Ok(files)}

pub fn copy_audio(directory:String,project:String,path:String)->Result<String,String>{let root=owner(&directory,&project)?;let source=PathBuf::from(path).canonicalize().map_err(|_|"Original recording is missing")?;let ext=source.extension().and_then(|s|s.to_str()).unwrap_or("").to_ascii_lowercase();if !["wav","mp3","m4a","aac","flac","ogg","opus","aiff","aif","wma"].contains(&ext.as_str()){return Err("Choose a supported recording".into())}let name=source.file_name().ok_or("Missing recording name")?.to_string_lossy();let target=safe(&root,&name)?;copy(&source,&target)?;Ok(target.to_string_lossy().into_owned())}
pub fn copy_workspace(directory:String,destination:String,project:String)->Result<String,String>{let from=owner(&directory,&project)?;let to=disk::root(&destination)?;if from==to{return Ok(to.to_string_lossy().into_owned())}if to.starts_with(&from)||from.starts_with(&to){return Err("Choose a separate project folder, not a parent or child of the current folder".into())}if to.join("Studio Link/project.json").exists(){return Err("The destination already contains Studio Link. Reconnect it instead of copying over it.".into())}let _lock=crate::media_organization::lock(&from)?;let mut paths=std::collections::BTreeSet::new();fn collect(root:&Path,path:&Path,out:&mut std::collections::BTreeSet<String>)->Result<(),String>{for e in fs::read_dir(path).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;let name=e.file_name().to_string_lossy().into_owned();if name.contains(".lock")||name.ends_with(".tmp"){continue}if e.file_type().map_err(|e|e.to_string())?.is_symlink(){continue}let path=e.path();if path.is_dir(){collect(root,&path,out)?;}else{out.insert(path.strip_prefix(root).unwrap().to_string_lossy().replace('\\',"/"));}}Ok(())}collect(&from,&from.join("Studio Link"),&mut paths)?;
 for name in ["project.json","media-index.json","storyboard-outputs.json"]{let v:Value=serde_json::from_slice(&fs::read(from.join("Studio Link").join(name)).unwrap_or_else(|_|b"{}".to_vec())).map_err(|e|e.to_string())?;if name=="project.json"{for r in v["storyboards"].as_object().into_iter().flat_map(|r|r.values()){if let Some(rel)=r["relativePath"].as_str(){paths.insert(rel.to_string());}}if let Some(rel)=v["activeRecording"]["relativePath"].as_str(){paths.insert(rel.to_string());}}if name=="media-index.json"{for e in v["entries"].as_object().into_iter().flat_map(|e|e.values()){for field in ["files","referenceFiles","ignoredFiles"]{for f in e[field].as_array().into_iter().flatten(){if let Some(rel)=f["relativePath"].as_str(){paths.insert(rel.to_string());}}}}}}
 paths.remove("Studio Link/project.json");for rel in paths{let source=safe(&from,&rel)?;if source.is_file(){let target=safe(&to,&rel)?;copy(&source,&target)?;}}copy(&from.join("Studio Link/project.json"),&to.join("Studio Link/project.json"))?;Ok(to.to_string_lossy().into_owned())}

#[cfg(test)]mod tests{use super::*;fn root()->PathBuf{let p=std::env::temp_dir().join(format!("vault-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(p.join("Studio Link")).unwrap();fs::write(p.join("Studio Link/project.json"),r#"{"project":{"id":"p"}}"#).unwrap();p.canonicalize().unwrap()}
#[test]fn exact_copy_survives_original_deletion_and_restores_working_file(){let p=root();let source=p.join("original.png");fs::write(&source,b"full resolution original").unwrap();let copied=preserve(p.to_string_lossy().into(),"p".into(),vec![json!({"id":"drawing-one","path":source})],true).unwrap();fs::remove_file(&source).unwrap();let f=&copied[0];fs::remove_file(p.join(f["relativePath"].as_str().unwrap())).unwrap();restore(p.to_string_lossy().into(),"p".into(),vec![f.clone()]).unwrap();assert_eq!(fs::read(p.join(f["relativePath"].as_str().unwrap())).unwrap(),b"full resolution original");fs::remove_dir_all(p).unwrap();}
#[test]fn backup_is_a_copy_and_unchanged_close_does_not_create_another(){let p=root();let snapshot=r#"{"format":"storyboardstudio-v01","project":{"id":"p","chapters":[]},"assets":[]}"#;assert_eq!(backup(&p.join("backups"),"p",snapshot,true).unwrap()["saved"],true);assert_eq!(backup(&p.join("backups"),"p",snapshot,true).unwrap()["saved"],false);assert_eq!(backup_files(&p.join("backups/p")).unwrap().len(),1);assert!(!p.join("p.StoryboardStudio").exists());fs::remove_dir_all(p).unwrap();}
#[test]fn four_backups_and_twenty_minute_guard_keep_the_newest_valid_snapshot(){let p=root();let folder=p.join("backups");for n in 0..7{let snapshot=json!({"format":"storyboardstudio-v01","project":{"id":"p","chapters":[],"edit":n},"assets":[]}).to_string();assert_eq!(backup(&folder,"p",&snapshot,true).unwrap()["saved"],true);}let files=backup_files(&folder.join("p")).unwrap();assert_eq!(files.len(),4);let last:Value=serde_json::from_slice(&fs::read(files.last().unwrap()).unwrap()).unwrap();assert_eq!(last["project"]["edit"],6);let changed=json!({"format":"storyboardstudio-v01","project":{"id":"p","chapters":[],"edit":7},"assets":[]}).to_string();assert_eq!(backup(&folder,"p",&changed,false).unwrap()["reason"],"interval");assert_eq!(backup_files(&folder.join("p")).unwrap().len(),4);fs::remove_dir_all(p).unwrap();}
#[test]fn trash_preserves_shared_recovery_bytes(){let p=root();let source=p.join("original.png");fs::write(&source,b"shared original").unwrap();let files=preserve(p.to_string_lossy().into(),"p".into(),vec![json!({"id":"old","path":source})],true).unwrap();let f=files[0].clone();let mut other=f.clone();other["id"]=json!("active");other["relativePath"]=json!("active.png");fs::write(p.join("Studio Link/media-index.json"),json!({"entries":{"active":{"files":[other],"removed":false}}}).to_string()).unwrap();let result=trash_with(p.to_string_lossy().into(),"p".into(),vec![f.clone()],vec![],|path|fs::rename(path,p.join("mock-trash.png")).map_err(|e|e.to_string())).unwrap();assert!(!p.join(f["relativePath"].as_str().unwrap()).exists());assert!(p.join(f["vaultRelativePath"].as_str().unwrap()).exists());assert_eq!(result["completedVersions"].as_array().unwrap().len(),1);fs::remove_dir_all(p).unwrap();}

}

#[cfg(test)]mod supervisor_state_tests{
 use super::*;
 #[test]fn audit_clears_stale_missing_and_verifies_recovery_contents(){
  let root=std::env::temp_dir().join(format!("supervisor-state-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(root.join("Studio Link")).unwrap();fs::write(root.join("Studio Link/project.json"),json!({"project":{"id":"p"}}).to_string()).unwrap();fs::write(root.join("image.png"),b"cleanup").unwrap();let fp=crate::owned_output::file_fingerprint(&root.join("image.png")).unwrap();let checked=audit(root.to_string_lossy().into_owned(),"p".into(),vec![json!({"relativePath":"image.png","missing":true,"state":"missing","fingerprint":fp,"verifyFingerprint":true})]).unwrap();assert_eq!(checked["files"][0]["state"],"ok");assert_eq!(checked["files"][0]["missing"],false);assert_eq!(checked["files"][0]["observedFingerprint"],fp);fs::remove_dir_all(root).unwrap();
 }
}

pub fn backup_health(folder:&Path,project:&str)->Result<Value,String>{if !project.chars().all(|c|c.is_ascii_alphanumeric()||c=='-'){return Err("Invalid project identity".into())}let dir=folder.join(project);if !dir.exists(){return Ok(json!({"valid":0,"issues":[],"checked":0}))}let mut valid=0;let mut checked=0;let mut issues=Vec::new();for entry in fs::read_dir(dir).map_err(|e|e.to_string())?{let p=entry.map_err(|e|e.to_string())?.path();if p.extension().and_then(|e|e.to_str())!=Some("StoryboardStudio"){continue}checked+=1;let name=p.file_name().unwrap_or_default().to_string_lossy();if fs::metadata(&p).map_err(|e|e.to_string())?.len()>128*1024*1024{issues.push(format!("{name}: large backup was not deeply checked"));continue}match fs::read(&p).map_err(|e|e.to_string()).and_then(|b|serde_json::from_slice::<Value>(&b).map_err(|e|e.to_string())){Ok(v)if v["format"]=="storyboardstudio-v01"&&v["project"]["id"]==project&&v["project"]["chapters"].is_array()&&v["assets"].is_array()=>valid+=1,_=>issues.push(format!("{name}: backup needs review"))}}if checked>4{issues.push("More than four recovery snapshots are present".into());}Ok(json!({"valid":valid,"checked":checked,"issues":issues}))}

#[cfg(test)]mod patch012_tests{
 use super::*;
 fn setup()->PathBuf{let root=std::env::temp_dir().join(format!("media012-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(root.join("Studio Link")).unwrap();fs::write(root.join("Studio Link/project.json"),json!({"project":{"id":"p"}}).to_string()).unwrap();fs::write(root.join("Studio Link/media-index.json"),r#"{"entries":{}}"#).unwrap();root.canonicalize().unwrap()}
 #[test]fn png_working_copy_preserves_original_and_dimensions(){use base64::Engine;let root=setup();let original=root.join("original.jpg");fs::write(&original,b"original JPEG bytes").unwrap();let png=b"\x89PNG\r\n\x1a\nfull-sized transparent PNG";let out=preserve(root.to_string_lossy().into(),"p".into(),vec![json!({"id":"m","path":original,"kind":"image","width":321,"height":123,"pngData":base64::engine::general_purpose::STANDARD.encode(png)})],true).unwrap();let f=&out[0];assert!(f["relativePath"].as_str().unwrap().ends_with(".png"));assert_eq!(fs::read(root.join(f["relativePath"].as_str().unwrap())).unwrap(),png);assert_eq!(f["width"],321);assert_eq!(f["height"],123);assert!(f.get("pngData").is_none());assert_eq!(fs::read(original).unwrap(),b"original JPEG bytes");fs::remove_dir_all(root).unwrap();}
 #[test]fn accepting_a_working_edit_updates_current_recovery(){let root=setup();let original=root.join("original.png");fs::write(&original,b"first version").unwrap();let first=preserve(root.to_string_lossy().into(),"p".into(),vec![json!({"id":"m","path":original})],true).unwrap();let mut file=first[0].clone();let working=root.join(file["relativePath"].as_str().unwrap());fs::write(&working,b"new edited pixels").unwrap();file["contentFingerprint"]=json!(crate::owned_output::file_fingerprint(&working).unwrap());let out=preserve(root.to_string_lossy().into(),"p".into(),vec![file],false).unwrap();let f=&out[0];assert_eq!(f["relativePath"],first[0]["relativePath"]);assert_ne!(f["vaultRelativePath"],first[0]["vaultRelativePath"]);assert_eq!(fs::read(root.join(f["vaultRelativePath"].as_str().unwrap())).unwrap(),b"new edited pixels");retire_superseded(root.to_string_lossy().into(),"p".into(),vec![f.clone()],vec![f.clone()]).unwrap();assert!(!root.join(first[0]["vaultRelativePath"].as_str().unwrap()).exists());assert_eq!(fs::read(original).unwrap(),b"first version");fs::remove_dir_all(root).unwrap();}
 #[test]fn refused_trash_keeps_entry_and_file(){let root=setup();let source=root.join("source.png");fs::write(&source,b"preserved").unwrap();let files=preserve(root.to_string_lossy().into(),"p".into(),vec![json!({"id":"m","path":source})],true).unwrap();let out=trash_with(root.to_string_lossy().into(),"p".into(),vec![files[0].clone()],vec![],|_|Err("unavailable".into())).unwrap();assert_eq!(out["completedVersions"].as_array().unwrap().len(),0);assert_eq!(out["errors"].as_array().unwrap().len(),1);assert!(root.join(files[0]["relativePath"].as_str().unwrap()).exists());fs::remove_dir_all(root).unwrap();}
 #[test]fn backup_inspection_never_rewrites_or_removes_files(){let root=setup();let backups=root.join("backups/p");fs::create_dir_all(&backups).unwrap();let snapshot=json!({"format":"storyboardstudio-v01","project":{"id":"p","chapters":[]},"assets":[]}).to_string();fs::write(backups.join("valid.StoryboardStudio"),&snapshot).unwrap();fs::write(backups.join("broken.StoryboardStudio"),b"not valid").unwrap();let checked=backup_health(&root.join("backups"),"p").unwrap();assert_eq!(checked["valid"],1);assert_eq!(checked["checked"],2);assert_eq!(checked["issues"].as_array().unwrap().len(),1);assert_eq!(fs::read_to_string(backups.join("valid.StoryboardStudio")).unwrap(),snapshot);assert_eq!(fs::read(backups.join("broken.StoryboardStudio")).unwrap(),b"not valid");fs::remove_dir_all(root).unwrap();}
}
